using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Constructor_WithItems_SetsPageIndexAndTotalPages()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var result = new PaginatedList<string>(items, 10, 2, 3);

            // Assert
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(4, result.TotalPages); // ceil(10/3) = 4
            Assert.Equal(3, result.Count);
            Assert.Contains("a", result);
            Assert.Contains("b", result);
            Assert.Contains("c", result);
        }

        [Fact]
        public void Constructor_WithEmptyItems_CreatesEmptyList()
        {
            // Arrange & Act
            var result = new PaginatedList<int>(new List<int>(), 0, 1, 10);

            // Assert
            Assert.Empty(result);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(0, result.TotalPages);
        }

        [Theory]
        [InlineData(10, 5, 2)]   // 10/5 = 2
        [InlineData(11, 5, 3)]   // ceil(11/5) = 3
        [InlineData(1, 10, 1)]   // ceil(1/10) = 1
        [InlineData(0, 10, 0)]   // ceil(0/10) = 0
        [InlineData(100, 10, 10)]
        public void TotalPages_CalculatedCorrectly(int totalCount, int pageSize, int expectedTotalPages)
        {
            // Act
            var result = new PaginatedList<int>(new List<int>(), totalCount, 1, pageSize);

            // Assert
            Assert.Equal(expectedTotalPages, result.TotalPages);
        }

        [Theory]
        [InlineData(1, false)]   // First page has no previous
        [InlineData(2, true)]    // Second page has previous
        [InlineData(3, true)]
        public void HasPreviousPage_ReturnsCorrectValue(int pageIndex, bool expected)
        {
            var result = new PaginatedList<int>(new List<int>(), 100, pageIndex, 10);
            Assert.Equal(expected, result.HasPreviousPage);
        }

        [Theory]
        [InlineData(1, 10, 10, true)]    // Page 1 of 10 — has next
        [InlineData(10, 10, 10, false)]  // Page 10 of 10 — no next
        [InlineData(5, 50, 10, true)]    // Page 5 of 5 — no next
        [InlineData(1, 5, 10, false)]    // Only 1 page total
        public void HasNextPage_ReturnsCorrectValue(int pageIndex, int totalCount, int pageSize, bool expected)
        {
            var result = new PaginatedList<int>(new List<int>(), totalCount, pageIndex, pageSize);
            Assert.Equal(expected, result.HasNextPage);
        }

        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            // Arrange
            var source = Enumerable.Range(1, 50).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 2, 10);

            // Assert
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(5, result.TotalPages);
            Assert.Equal(10, result.Count);
            Assert.Equal(11, result.First());
            Assert.Equal(20, result.Last());
        }

        [Fact]
        public void Create_FirstPage_ReturnsFirstItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.Equal(10, result.Count);
