using System;
using Xunit;
using ContosoUniversity.Services;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain any leftover notifications from the static queue
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _service.Dispose();
        }

        [Fact]
        public void SendNotification_ThenReceive_ReturnsNotification()
        {
            // Act
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("Student 'John Doe'", notification.Message);
            Assert.Contains("created", notification.Message);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            _service.SendNotification("Course", "100", "Math 101", EntityOperation.UPDATE);

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdFormat()
        {
            _service.SendNotification("Student", "42", EntityOperation.DELETE);

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("Student (ID: 42)", notification.Message);
            Assert.Contains("deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_CreateOperation_GeneratesCorrectMessage()
        {
            _service.SendNotification("Department", "1", "Engineering", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();
            Assert.Equal("New Department 'Engineering' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateOperation_GeneratesCorrectMessage()
        {
            _service.SendNotification("Department", "1", "Engineering", EntityOperation.UPDATE);

            var notification = _service.ReceiveNotification();
            Assert.Equal("Department 'Engineering' has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesCorrectMessage()
        {
            _service.SendNotification("Department", "1", "Engineering", EntityOperation.DELETE);

            var notification = _service.ReceiveNotification();
            Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_WithNullDisplayName_UsesIdFormat()
        {
            _service.SendNotification("Student", "5", null, EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();
            Assert.Contains("Student (ID: 5)", notification.Message);
        }

        [Fact]
        public void SendNotification_WithEmptyDisplayName_UsesIdFormat()
        {
            _service.SendNotification("Student", "5", "", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();
            Assert.Contains("Student (ID: 5)", notification.Message);
        }

        [Fact]
        public void SendNotification_WithWhitespaceDisplayName_UsesIdFormat()
        {
            _service.SendNotification("Student", "5", "   ", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();
            Assert.Contains("Student (ID: 5)", notification.Message);
        }

        [Fact]
        public void ReceiveNotification_WhenQueueEmpty_ReturnsNull()
        {
            var result = _service.ReceiveNotification();
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_DequeuesInFIFOOrder()
        {
            _service.SendNotification("A", "1", "First", EntityOperation.CREATE);
            _service.SendNotification("B", "2", "Second", EntityOperation.UPDATE);
            _service.SendNotification("C", "3", "Third", EntityOperation.DELETE);

            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();
            var third = _service.ReceiveNotification();

            Assert.Equal("A", first.EntityType);
            Assert.Equal("B", second.EntityType);
            Assert.Equal("C", third.EntityType);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op for in-memory implementation
            var ex = Record.Exception(() => _service.MarkAsRead(42));
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_SetsCreatedAt()
        {
            var before = DateTime.Now;
            _service.SendNotification("Test", "1", "Item", EntityOperation.CREATE);
            var after = DateTime.Now;

            var notification = _service.ReceiveNotification();
            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var ex = Record.Exception(() => service.Dispose());
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_TwoArgOverload_CallsFiveArgOverload()
        {
            // The 2-arg overload (entityType, entityId, operation) delegates to the 5-arg version
            _service.SendNotification("Instructor", "10", EntityOperation.UPDATE);

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Instructor", notification.EntityType);
            Assert.Equal("10", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Equal("System", notification.CreatedBy);
        }
    }
}

