using System;
using System.Linq;
using Xunit;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers
{
    public class HomeControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly HomeController _controller;

        public HomeControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new HomeController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Contact_ReturnsViewResult()
        {
            var result = _controller.Contact();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("Your contact page.", _controller.ViewBag.Message);
        }

        [Fact]
        public void Error_ReturnsViewResult()
        {
            var result = _controller.Error();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Unauthorized_ReturnsViewResult_WithMessage()
        {
            var result = _controller.Unauthorized();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("You don't have permission to access this resource.", _controller.ViewBag.Message);
        }

        [Fact]
        public void About_ReturnsViewResult_WithEnrollmentDateGroups()
        {
            // Arrange - seed some students
            _context.Students.Add(new Student
            {
                FirstMidName = "Alice",
                LastName = "Smith",
                EnrollmentDate = new DateTime(2023, 9, 1)
            });
            _context.Students.Add(new Student
            {
                FirstMidName = "Bob",
                LastName = "Jones",
                EnrollmentDate = new DateTime(2023, 9, 1)
            });
            _context.Students.Add(new Student
            {
                FirstMidName = "Charlie",
                LastName = "Brown",
                EnrollmentDate = new DateTime(2022, 9, 1)
            });
            _context.SaveChanges();

            // Act
            var result = _controller.About();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Models.SchoolViewModels.EnrollmentDateGroup>>(viewResult.Model);
            Assert.Equal(2, model.Count); // 2 distinct enrollment dates

            var group2023 = model.Single(g => g.EnrollmentDate == new DateTime(2023, 9, 1));
            Assert.Equal(2, group2023.StudentCount);

            var group2022 = model.Single(g => g.EnrollmentDate == new DateTime(2022, 9, 1));
            Assert.Equal(1, group2022.StudentCount);
        }

        [Fact]
        public void About_WithNoStudents_ReturnsEmptyList()
        {
            var result = _controller.About();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Models.SchoolViewModels.EnrollmentDateGroup>>(viewResult.Model);
            Assert.Empty(model);
        }
    }
}

