namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new InstructorsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Instructor SeedInstructorWithCourses()
        {
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course1 = new Course { CourseID = 1001, Title = "Course A", Credits = 3, DepartmentID = dept.DepartmentID };
            var course2 = new Course { CourseID = 1002, Title = "Course B", Credits = 4, DepartmentID = dept.DepartmentID };
            _context.Courses.AddRange(course1, course2);
            _context.SaveChanges();

            var instructor = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = new DateTime(1995, 3, 11),
                OfficeAssignment = new OfficeAssignment { Location = "Smith 17" },
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = course1.CourseID },
                    new CourseAssignment { CourseID = course2.CourseID }
                }
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            return instructor;
        }

        private void SeedMultipleInstructors()
        {
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course { CourseID = 2001, Title = "Test Course", Credits = 3, DepartmentID = dept.DepartmentID };
            _context.Courses.Add(course);
            _context.SaveChanges();

            _context.Instructors.AddRange(
                new Instructor
                {
                    FirstMidName = "Kim",
                    LastName = "Abercrombie",
                    HireDate = new DateTime(1995, 3, 11),
                    CourseAssignments = new List<CourseAssignment>()
                },
                new Instructor
                {
                    FirstMidName = "Fadi",
                    LastName = "Fakhouri",
                    HireDate = new DateTime(2002, 7, 6),
                    CourseAssignments = new List<CourseAssignment>
                    {
                        new CourseAssignment { CourseID = course.CourseID }
                    }
                }
            );
            _context.SaveChanges();
        }

        // --- Index Tests ---

        [Fact]
        public void Index_ReturnsViewResult_WithInstructorIndexData()
        {
            SeedMultipleInstructors();

            var result = _controller.Index(null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<Models.SchoolViewModels.InstructorIndexData>(viewResult.Model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_ShowsCoursesForInstructor()
        {
            SeedMultipleInstructors();
            var fakhouri = _context.Instructors.First(i => i.LastName == "Fakhouri");

            var result = _controller.Index(fakhouri.ID, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<Models.SchoolViewModels.InstructorIndexData>(viewResult.Model);
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
        }

