using System;
using System.Collections.Generic;
using Xunit;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Http;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };

            // Drain any leftover notifications from the static queue
            var service = new NotificationService();
            while (service.ReceiveNotification() != null) { }
            service.Dispose();
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void GetNotifications_WhenNoNotifications_ReturnsEmptyList()
        {
            var result = _controller.GetNotifications();

            Assert.IsType<JsonResult>(result);
            // Verify the result has success and count properties
            var value = result.Value;
            Assert.NotNull(value);
            var type = value.GetType();
            var successProp = type.GetProperty("success");
            var countProp = type.GetProperty("count");
            Assert.NotNull(successProp);
            Assert.NotNull(countProp);
            Assert.True((bool)successProp.GetValue(value));
            Assert.Equal(0, (int)countProp.GetValue(value));
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsNotifications()
        {
            // Use the controller's inherited notificationService to enqueue
            var service = new NotificationService();
            service.SendNotification("Student", "1", "Alice Smith", EntityOperation.CREATE);
            service.SendNotification("Course", "100", "Math", EntityOperation.UPDATE);
            service.Dispose();

            var result = _controller.GetNotifications();

            var value = result.Value;
            var successProp = value.GetType().GetProperty("success");
            var countProp = value.GetType().GetProperty("count");
            var notifProp = value.GetType().GetProperty("notifications");
            Assert.True((bool)successProp.GetValue(value));

            var count = (int)countProp.GetValue(value);
            Assert.True(count >= 1, $"Expected at least 1 notification, got {count}");

            var notifications = notifProp.GetValue(value) as List<Notification>;
            Assert.NotNull(notifications);
            Assert.True(notifications.Count >= 1);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            var result = _controller.MarkAsRead(1);

            Assert.IsType<JsonResult>(result);
            var value = result.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(value));
        }

        [Fact]
        public void GetNotifications_LimitsTo10()
        {
            // Enqueue more than 10 notifications
            var service = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                service.SendNotification("Type", i.ToString(), $"Item {i}", EntityOperation.CREATE);
            }
            service.Dispose();

            var result = _controller.GetNotifications();

            var value = result.Value;
            var countProp = value.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(value);
            Assert.True(count <= 10, $"Expected at most 10 notifications, got {count}");
        }
    }
}

