using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using Xunit;
using Moq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Hosting;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerExtendedTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _tempDir;

        public CoursesControllerExtendedTests()
        {
            _context = TestDbContextFactory.Create();
            _tempDir = Path.Combine(Path.GetTempPath(), "contoso_test_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(_tempDir);
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);
            _mockLogger = new Mock<ILogger<CoursesController>>();
            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            try { Directory.Delete(_tempDir, true); } catch { }
        }

        private Department SeedDepartment()
        {
            var dept = new Department
            {
                Name = "Engineering",
                Budget = 350000,
                StartDate = new DateTime(2007, 9, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(int deptId)
        {
            var course = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = deptId };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        [Fact]
        public void Create_POST_WithValidImageFile_UploadsAndSetsPath()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 8001,
                Title = "Test Upload",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var content = new byte[] { 0xFF, 0xD8, 0xFF }; // JPEG magic bytes
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("photo.jpg");
            mockFile.Setup(f => f.Length).Returns(content.Length);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()))
                    .Callback<Stream>(s => s.Write(content, 0, content.Length));

            var result = _controller.Create(course, mockFile.Object);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);

            var saved = _context.Courses.Find(8001);
            Assert.NotNull(saved.TeachingMaterialImagePath);
            Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void Create_POST_AllowedExtensions_AreAccepted(string ext)
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 8100 + Math.Abs(ext.GetHashCode() % 100),
                Title = "Test",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns($"image{ext}");
            mockFile.Setup(f => f.Length).Returns(100);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, mockFile.Object);

            Assert.IsType<RedirectToActionResult>(result);
        }

        [Theory]
        [InlineData(".exe")]
        [InlineData(".bat")]
        [InlineData(".pdf")]
        [InlineData(".doc")]
        public void Create_POST_DisallowedExtensions_AreRejected(string ext)
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 8200 + Math.Abs(ext.GetHashCode() % 100),
                Title = "Test",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns($"file{ext}");
            mockFile.Setup(f => f.Length).Returns(100);

            var result = _controller.Create(course, mockFile.Object);

            Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_POST_WithValidImageFile_UploadsAndUpdatesPath()
        {
            var dept = SeedDepartment();
            var course = SeedCourse(dept.DepartmentID);
            _context.Entry(course).State = EntityState.Detached;

            var updated = new Course
            {
                CourseID = course.CourseID,
                Title = course.Title,
                Credits = course.Credits,
                DepartmentID = course.DepartmentID
            };

            var content = new byte[] { 0x89, 0x50, 0x4E, 0x47 }; // PNG magic bytes
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("new_image.png");
            mockFile.Setup(f => f.Length).Returns(content.Length);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()))
                    .Callback<Stream>(s => s.Write(content, 0, content.Length));

            var result = _controller.Edit(updated, mockFile.Object);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
        }

        [Fact]
        public void Edit_POST_WithExistingImage_DeletesOldFile()
        {
            var dept = SeedDepartment();
            // Create a course with an existing image path
            var course = new Course
            {
                CourseID = 8300,
                Title = "OldImage",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/old_image.jpg"
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            _context.Entry(course).State = EntityState.Detached;

            // Create the old file
            var uploadsPath = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(uploadsPath);
            File.WriteAllText(Path.Combine(uploadsPath, "old_image.jpg"), "old content");

            var updated = new Course
            {
                CourseID = 8300,
                Title = "OldImage",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/old_image.jpg"
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("new.png");
            mockFile.Setup(f => f.Length).Returns(10);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Edit(updated, mockFile.Object);

            Assert.IsType<RedirectToActionResult>(result);
            // Old file should have been deleted
            Assert.False(File.Exists(Path.Combine(uploadsPath, "old_image.jpg")));
        }

        [Fact]
        public void Edit_POST_WithFileTooLarge_ReturnsViewWithError()
        {
            var dept = SeedDepartment();
            var course = SeedCourse(dept.DepartmentID);
            _context.Entry(course).State = EntityState.Detached;

            var updated = new Course
            {
                CourseID = course.CourseID,
                Title = course.Title,
                Credits = course.Credits,
                DepartmentID = course.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("big.jpg");
            mockFile.Setup(f => f.Length).Returns(10 * 1024 * 1024);

            var result = _controller.Edit(updated, mockFile.Object);

            Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void DeleteConfirmed_WithImageFile_DeletesFileFromDisk()
        {
            var dept = SeedDepartment();
            var uploadsPath = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
            Directory.CreateDirectory(uploadsPath);
            var imagePath = Path.Combine(uploadsPath, "test_delete.jpg");
            File.WriteAllText(imagePath, "test");

            var course = new Course
            {
                CourseID = 8400,
                Title = "DeleteMe",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = "/Uploads/TeachingMaterials/test_delete.jpg"
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            _controller.DeleteConfirmed(8400);

            Assert.False(File.Exists(imagePath));
            Assert.Null(_context.Courses.Find(8400));
        }

        [Fact]
        public void DeleteConfirmed_WithoutImageFile_StillDeletesCourse()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 8500,
                Title = "NoImage",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                TeachingMaterialImagePath = null
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(8500);

            Assert.IsType<RedirectToActionResult>(result);
            Assert.Null(_context.Courses.Find(8500));
        }

        [Fact]
        public void Create_POST_WhenFileUploadThrows_ReturnsViewWithError()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 8600,
                Title = "ErrorUpload",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("photo.jpg");
            mockFile.Setup(f => f.Length).Returns(100);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())).Throws(new IOException("Disk full"));

            var result = _controller.Create(course, mockFile.Object);

            Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_POST_WhenFileUploadThrows_ReturnsViewWithError()
        {
            var dept = SeedDepartment();
            var course = SeedCourse(dept.DepartmentID);
            _context.Entry(course).State = EntityState.Detached;

            var updated = new Course
            {
                CourseID = course.CourseID,
                Title = course.Title,
                Credits = course.Credits,
                DepartmentID = course.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("photo.jpg");
            mockFile.Setup(f => f.Length).Returns(100);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())).Throws(new IOException("Disk full"));

            var result = _controller.Edit(updated, mockFile.Object);

            Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
