using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerExtendedTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerExtendedTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new InstructorsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private (Department dept, Course course1, Course course2) SeedBasicData()
        {
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course1 = new Course { CourseID = 5001, Title = "Course A", Credits = 3, DepartmentID = dept.DepartmentID };
            var course2 = new Course { CourseID = 5002, Title = "Course B", Credits = 4, DepartmentID = dept.DepartmentID };
            _context.Courses.AddRange(course1, course2);
            _context.SaveChanges();

            return (dept, course1, course2);
        }

        [Fact]
        public void Index_WithInstructorAndCourseSelected_ShowsEnrollments()
        {
            var (dept, course1, _) = SeedBasicData();

            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Now
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            var enrollment = new Enrollment
            {
                StudentID = student.ID,
                CourseID = course1.CourseID,
                Grade = Grade.A
            };
            course1.Enrollments = new List<Enrollment> { enrollment };
            _context.Enrollments.Add(enrollment);

            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Teacher",
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = course1.CourseID }
                }
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var result = _controller.Index(instructor.ID, course1.CourseID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<InstructorIndexData>(viewResult.Model);
            Assert.NotNull(model.Courses);
            Assert.NotNull(model.Enrollments);
        }

        [Fact]
        public void Edit_GET_WithValidId_PopulatesAssignedCourseData()
        {
            var (dept, course1, course2) = SeedBasicData();

            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Teacher",
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = course1.CourseID }
                }
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var result = _controller.Edit(instructor.ID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var courses = _controller.ViewBag.Courses as List<AssignedCourseData>;
            Assert.NotNull(courses);
            Assert.Equal(2, courses.Count);

            var assignedCourse = courses.Single(c => c.CourseID == course1.CourseID);
            Assert.True(assignedCourse.Assigned);

            var unassignedCourse = courses.Single(c => c.CourseID == course2.CourseID);
            Assert.False(unassignedCourse.Assigned);
        }

        [Fact]
        public void Create_POST_WithNullSelectedCourses_DoesNotSetCourseAssignments()
        {
            var (dept, _, _) = SeedBasicData();

            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = new DateTime(2023, 1, 1)
            };

            var result = _controller.Create(instructor, null);

            Assert.IsType<RedirectToActionResult>(result);
            var saved = _context.Instructors.Include(i => i.CourseAssignments).First(i => i.LastName == "Instructor");
            // No course assignments should be set
            Assert.Null(saved.CourseAssignments);
        }

        [Fact]
        public void Create_POST_WithEmptySelectedCourses_SetsCourseAssignments()
        {
            var (dept, _, _) = SeedBasicData();

            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Inst2",
                HireDate = new DateTime(2023, 1, 1)
            };

            var result = _controller.Create(instructor, new string[0]);

            Assert.IsType<RedirectToActionResult>(result);
        }

        [Fact]
        public void Create_POST_WithMultipleSelectedCourses_AddsAll()
        {
            var (dept, course1, course2) = SeedBasicData();

            var instructor = new Instructor
            {
                FirstMidName = "Multi",
                LastName = "Course",
                HireDate = new DateTime(2023, 1, 1)
            };

            var result = _controller.Create(instructor, new[] { "5001", "5002" });

            Assert.IsType<RedirectToActionResult>(result);
            var saved = _context.Instructors.Include(i => i.CourseAssignments).First(i => i.LastName == "Course");
            Assert.Equal(2, saved.CourseAssignments.Count);
        }

        [Fact]
        public void DeleteConfirmed_RemovesInstructor_EvenWithOfficeAssignment()
        {
            var (dept, _, _) = SeedBasicData();

            var instructor = new Instructor
            {
                FirstMidName = "WithOffice",
                LastName = "ToDelete",
                HireDate = new DateTime(2020, 1, 1),
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" },
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var result = _controller.DeleteConfirmed(instructor.ID);

            var redirectResult = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirectResult.ActionName);
            Assert.Null(_context.Instructors.Find(instructor.ID));
        }

        [Fact]
        public void Index_OrdersInstructorsByLastName()
        {
            var (dept, _, _) = SeedBasicData();

            _context.Instructors.AddRange(
                new Instructor { FirstMidName = "Z", LastName = "Zebra", HireDate = DateTime.Now, CourseAssignments = new List<CourseAssignment>() },
                new Instructor { FirstMidName = "A", LastName = "Apple", HireDate = DateTime.Now, CourseAssignments = new List<CourseAssignment>() }
            );
            _context.SaveChanges();

            var result = _controller.Index(null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<InstructorIndexData>(viewResult.Model);
            var instructors = model.Instructors.ToList();
            Assert.Equal("Apple", instructors[0].LastName);
            Assert.Equal("Zebra", instructors[1].LastName);
        }
    }
}

