    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(source, 1, 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
    }

    [Fact]
    public void HasPreviousPage_AtBoundary_PageOne_ReturnsFalse()
    {
        // Exact boundary: PageIndex == 1 means no previous
        var result = new PaginatedList<int>(new List<int>(), 100, 1, 10);
        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_AtBoundary_LastPage_ReturnsFalse()
    {
        // Exact boundary: PageIndex == TotalPages means no next
        var result = new PaginatedList<int>(new List<int>(), 30, 3, 10); // 3 pages, on page 3
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_JustBeforeLastPage_ReturnsTrue()
    {
        // PageIndex < TotalPages
        var result = new PaginatedList<int>(new List<int>(), 30, 2, 10); // 3 pages, on page 2
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void Create_SkipsCorrectNumberOfItems()
    {
        // Verify that (pageIndex - 1) * pageSize skip formula is correct
        var source = Enumerable.Range(1, 30).AsQueryable();

        var page2 = PaginatedList<int>.Create(source, 2, 10);
        // Page 2 should skip first 10 items (1-10) and return 11-20
        Assert.Equal(11, page2.First());
        Assert.Equal(20, page2.Last());
        Assert.Equal(10, page2.Count);

        var page1 = PaginatedList<int>.Create(source, 1, 10);
        // Page 1 should skip 0 items
        Assert.Equal(1, page1.First());
    }

    [Theory]
    [InlineData(10, 5, 2)]   // exact: ceil(10/5) = 2
    [InlineData(9, 5, 2)]    // non-exact: ceil(9/5) = 2, Floor would be 1
    public void TotalPages_CeilingVsFloor_VerifiesCeiling(int count, int pageSize, int expected)
    {
        var result = new PaginatedList<int>(new List<int>(), count, 1, pageSize);
        Assert.Equal(expected, result.TotalPages);
    }
}

