    // --- DeleteConfirmed Tests ---

    [Fact]
    public void DeleteConfirmed_RemovesStudentAndRedirects()
    {
        SeedStudents();
        var student = _context.Students.First();
        var initialCount = _context.Students.Count();

        var result = _controller.DeleteConfirmed(student.ID);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
        Assert.Equal(initialCount - 1, _context.Students.Count());
    }

    // --- Boundary and edge case tests (mutation gap coverage) ---

    [Fact]
    public void Index_WithNullPage_DefaultsToPage1()
    {
        SeedStudents();

        var result = _controller.Index(null, null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_WithEmptySearchString_ReturnsAllStudents()
    {
        SeedStudents();

        var result = _controller.Index(null, null, "", null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(3, model.Count); // All students returned when search is empty
    }

    [Fact]
    public void Create_POST_WithExactSqlMinDate_ShouldPass()
    {
        // Boundary: exactly 1753-01-01 should be valid (not < 1753-01-01)
        var student = new Student
        {
            FirstMidName = "Boundary",
            LastName = "Student",
            EnrollmentDate = new DateTime(1753, 1, 1)
        };

        var result = _controller.Create(student);

        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Create_POST_WithDateJustBeforeSqlMin_ShouldFail()
    {
        var student = new Student
        {
            FirstMidName = "Invalid",
            LastName = "Student",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        var result = _controller.Create(student);

        Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Details_WithValidId_ReturnsStudent_WithEnrollments()
    {
        SeedStudents();
        var student = _context.Students.First();

        var result = _controller.Details(student.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal(student.FirstMidName, model.FirstMidName);
        Assert.Equal(student.LastName, model.LastName);
        Assert.Equal(student.EnrollmentDate, model.EnrollmentDate);
    }

    [Fact]
    public void Create_POST_InvalidModelState_DoesNotAddToDatabase()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        _controller.Create(student);

        Assert.Empty(_context.Students);
    }
}

